 document.querySelectorAll('[data-person]').forEach(function(b){b.onclick=function(){var u=seconds/cycle();person=b.dataset.person;seconds=u*cycle();dirty=true;update();};});document.querySelectorAll('[data-angle]').forEach(function(b){b.onclick=function(){angle=+b.dataset.angle;dirty=true;update();};});document.querySelectorAll('[data-style]').forEach(function(b){b.onclick=function(){style=b.dataset.style;dirty=true;update();};});document.querySelectorAll('[data-phase]').forEach(function(b){b.onclick=function(){seek(+b.dataset.phase);};});
 document.getElementById('phase').oninput=function(){seek(+this.value/1000);};document.getElementById('pause').onclick=function(){paused=!paused;last=0;dirty=true;update();};document.getElementById('slow').onclick=function(){slow=!slow;dirty=true;update();};document.getElementById('back').onclick=function(){seconds-=1/60;paused=true;dirty=true;update();draw();};document.getElementById('next').onclick=function(){seconds+=1/60;paused=true;dirty=true;update();draw();};document.getElementById('restart').onclick=function(){seconds=0;dirty=true;last=0;};document.getElementById('fullscreen').onclick=function(){if(canvas.requestFullscreen)canvas.requestFullscreen().catch(function(){document.getElementById('status').textContent='Full screen is unavailable in this browser.';});};document.addEventListener('visibilitychange',function(){last=0;});
 window.ReferenceStudy={state:function(){return {loaded:loaded,failed:failed,seconds:seconds,person:person,angle:angle,style:style,paused:paused,slow:slow};},inspect:function(u,id,view,drawing){if(id)person=id;if(view!==undefined)angle=view;if(drawing)style=drawing;seek(u);}};
 var files={blouse:'../assets/cast/blouse.png',background:'../assets/street.png',sideUpper:'../assets/skin/resident-arms.png',sideLegs:'../assets/skin/resident-layered.png',props:'../assets/rig/resident.png',front:'../assets/directions/front.png',rear:'../assets/directions/rear.png',front45:'../assets/directions/front45.png',rear45:'../assets/directions/rear45.png',legs:'../assets/directions/legs.png'};
 Promise.all(Object.entries(files).map(function(entry){return new Promise(function(resolve,reject){var img=new Image();img.onload=function(){resolve([entry[0],img]);};img.onerror=reject;img.src=entry[1];});})).then(function(entries){images=Object.fromEntries(entries);['original','blouse'].forEach(function(id){var p=CastWorld.profiles[id],opts={compact:true,hideBag:!!p.hideBag,pose:function(s){return s.variant==='reference'?ReferenceWalk.actor(s):VisitPose.pose(s);}};if(p.art)opts.views=CastActor.views(images[p.art],CastFrames[p.art],p);renderers[id]=AlleyActor.renderer(ctx,p.art?{}:images,AlleyFrames,opts);});loaded=true;document.getElementById('loading').hidden=true;draw();}).catch(function(e){failed=true;loaded=false;document.getElementById('loading').hidden=false;document.getElementById('loading').textContent='The study artwork could not load. Please reload to try again.';console.error(e);});
 function tick(now){var dt=last?Math.min(.1,(now-last)/1000):0;last=now;if(!document.hidden){if(!paused)seconds+=dt*(slow?.5:1);if(!paused||dirty)draw();}requestAnimationFrame(tick);}update();requestAnimationFrame(tick);
